//! Heading ranks share one canonical interface without changing their node names.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><h1 id=h1>One</h1><h2 id=h2>Two</h2><h3 id=h3>Three</h3><h4 id=h4>Four</h4><h5 id=h5>Five</h5><h6 id=h6>Six</h6><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://heading-interface.test/dir/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn heading_interface_all_six_native_ranks_share_canonical_constructor_prototype_and_brand(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var C=HTMLHeadingElement,P=C.prototype;for(var rank=1;rank<=6;rank++){var tag='h'+rank,x=document.getElementById(tag);if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||x.constructor!==C||x.localName!==tag||x.tagName!==tag.toUpperCase()||Object.prototype.toString.call(x)!=='[object HTMLHeadingElement]')throw 'shared native heading interface';}if(P.constructor!==C||Object.getPrototypeOf(P)!==HTMLElement.prototype||Object.getPrototypeOf(C)!==HTMLElement)throw 'canonical heading hierarchy';var caught=false;try{new C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal heading construction';"#);}
#[test]
fn heading_interface_inert_prefixes_exact_names_and_independent_import_keep_rank(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',C=HTMLHeadingElement;for(var rank=1;rank<=6;rank++){var tag='h'+rank,x=doc.createElementNS(html,'t:'+tag);x.title='raw\ud800';var attr=x.getAttributeNode('title'),copy=x.cloneNode(false),native=document.importNode(x,false);if(!(x instanceof C)||!(copy instanceof C)||!(native instanceof C)||x.prefix!=='t'||copy.localName!==tag||native.localName!==tag||copy.title!==x.title||native.title!==x.title||copy.getAttributeNode('title')===attr||native.getAttributeNode('title')===attr||x.ownerDocument!==doc||native.ownerDocument!==document)throw 'actual exact heading copies';}for(var wrong of [doc.createElementNS('urn:foreign','h1'),doc.createElementNS(html,'H1'),doc.createElementNS(html,'h0'),doc.createElementNS(html,'h7'),doc.createElementNS(html,'hgroup'),document.body]){if(wrong instanceof C)throw 'exact heading brand';}"#);}
#[test]
fn heading_interface_native_copy_adoption_and_text_replacement_preserve_actual_nodes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document();for(var rank=1;rank<=6;rank++){var x=document.getElementById('h'+rank),first=x.firstChild,list=x.childNodes;x.title='rank-'+rank;var attr=x.getAttributeNode('title'),copy=x.cloneNode(true);if(!(copy instanceof HTMLHeadingElement)||copy.localName!==x.localName||copy.firstChild===first||copy.textContent!==x.textContent||copy.getAttributeNode('title')===attr)throw 'independent heading clone';if(doc.adoptNode(x)!==x||x.ownerDocument!==doc||x.parentNode!==null||x.firstChild!==first||x.childNodes!==list||x.getAttributeNode('title')!==attr||attr.ownerDocument!==doc)throw 'heading adoption identity';document.adoptNode(x);document.body.appendChild(x);copy.textContent='Changed\udfff';if(copy.textContent!=='Changed\udfff'||x.firstChild!==first||x.getAttributeNode('title')!==attr||!(x instanceof HTMLHeadingElement))throw 'actual heading replacement';}if(document.getElementById('neighbor').value!=='seed')throw 'neighbor state';"#);}

#[test]
fn heading_interface_saved_constructor_author_properties_and_forged_node_brands(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var C=HTMLHeadingElement,P=C.prototype,q=document.getElementById('h1'),b=document.getElementById('h6');q.constructor='author';if(q.constructor!=='author'||Object.getPrototypeOf(q)!==P||!(q instanceof C)||b.constructor!==C)throw 'author constructor does not change canonical class';delete q.constructor;delete window.HTMLHeadingElement;if(q.constructor!==C||!(q instanceof C)||!(b instanceof C)||Object.getPrototypeOf(b)!==P)throw 'saved heading constructor';var caught=false;try{Node.prototype.cloneNode.call(Object.create(P),true);}catch(e){caught=e instanceof TypeError;}if(!caught||q.textContent!=='One'||b.textContent!=='Six')throw 'forged heading has no native node authority';"#);
}

#[test]
fn heading_interface_dynamic_connection_template_parking_and_inert_fallback_keep_authority(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml';for(var tag of ['h1','h2','h3','h4','h5','h6']){var x=doc.createElementNS(html,tag);x.setAttribute('title','A\ud800Z');x.appendChild(doc.createTextNode('Fallback'));var first=x.firstChild,attr=x.getAttributeNode('title'),list=x.childNodes;document.body.appendChild(x);if(!(x instanceof HTMLHeadingElement)||x.ownerDocument!==document||x.firstChild!==first||x.getAttributeNode('title')!==attr||attr.value!=='A\ud800Z'||x.childNodes!==list)throw 'actual heading connection';var leaf=x.cloneNode(false),template=document.createElement('template');template.content.appendChild(leaf);document.body.appendChild(template);if(!(leaf instanceof HTMLHeadingElement)||leaf.parentNode!==template.content||leaf.ownerDocument!==template.content.ownerDocument||leaf.getAttribute('title')!=='A\ud800Z')throw 'parked heading class';var detached=doc.createElementNS(html,tag);detached.appendChild(doc.createTextNode('Before'));var old=detached.firstChild;detached.textContent='After\udfff';if(detached.textContent!=='After\udfff'||old.parentNode!==null||!(detached instanceof HTMLHeadingElement))throw 'inert heading fallback';}"#);
}

#[test]
fn heading_interface_child_saved_clone_origin_refusal_preserves_source_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var q=document.getElementById('h1'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,C=child.HTMLHeadingElement,saved=child.Node.prototype.cloneNode,copy=saved.call(q,true);if(C===HTMLHeadingElement||C.prototype===HTMLHeadingElement.prototype||Object.getPrototypeOf(C)!==child.HTMLElement||!(copy instanceof HTMLHeadingElement)||copy.textContent!=='One')throw 'owner heading interface and captured clone';"#);p.set_location(&crate::navigation::address("https://other-heading-interface.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();let e=p.runtime.execute("saved.call(q,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.set_location(&crate::navigation::address("https://heading-interface.test/dir/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"var again=saved.call(q,true);if(!(again instanceof HTMLHeadingElement)||again.textContent!=='One'||again===q)throw 'heading clone origin recovery';");
}

#[test]
fn heading_interface_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["h1","h2","h3","h4","h5","h6"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById(which);");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.setAttribute('title','exact');source.appendChild(doc.createTextNode('Fallback'));");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.setAttribute('title','exact');source.appendChild(doc.createTextNode('Fallback'));");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('title');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('title')!==oldValue||watch.takeRecords().length)throw 'atomic heading lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('title')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.getAttribute('title')!==source.getAttribute('title')||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}




#[test]
fn heading_interface_reserved_main_connection_needs_no_additional_node_slots(){
 for tag in ["h1","h2","h3","h4","h5","h6"]{for inert_owner in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,owner={},source=owner.createElementNS('http://www.w3.org/1999/xhtml','{tag}');source.setAttribute('title','exact');source.appendChild(owner.createTextNode('Reserved'));var first=source.firstChild,attr=source.getAttributeNode('title');",if inert_owner{"new Document()"}else{"document"}));let nodes=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(target.appendChild(source)!==source||source.ownerDocument!==document||source.firstChild!==first||source.getAttributeNode('title')!==attr||source.getAttribute('title')!=='exact'||source.parentNode!==target)throw 'reserved native heading connection';");assert_eq!(d.nodes.len(),nodes);p.state.node_limit=limit;}}
}




#[test]
fn heading_interface_clone_import_active_content_guards_preserve_source(){
 let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag,attrs,..}=&mut node.kind{if tag=="h1"{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('h1'),doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','h1'),frame=doc.createElementNS('http://www.w3.org/1999/xhtml','iframe');source.appendChild(frame);");for code in ["x.cloneNode(true);","document.importNode(source,true);"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("unavailable")||e.contains("implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.firstChild!==frame||frame.parentNode!==source||source.ownerDocument!==doc||x.textContent!=='One')throw 'active content copy guard';");}
}




#[test]
fn heading_interface_existing_raw_name_aliases_and_live_queries_keep_exact_values(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var rank=1;rank<=6;rank++){var x=document.getElementById('h'+rank),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.setAttribute('name','A\ud800'+rank);var attr=x.getAttributeNode('name');attr.value='B\udfff'+rank;attr.nodeValue='C\ud800'+rank;attr.textContent='D\udfff'+rank;var copy=x.cloneNode(false),records=watch.takeRecords();if(x.getAttribute('name')!=='D\udfff'+rank||copy.getAttribute('name')!==attr.value||x.getAttributeNode('name')!==attr||copy.getAttributeNode('name')===attr||document.getElementsByName(attr.value)[0]!==x||records.length!==4||records[1].oldValue!=='A\ud800'+rank||!(copy instanceof HTMLHeadingElement))throw 'existing exact heading name authority';watch.disconnect();}"#);
}

#[test]
fn heading_interface_namespaced_attribute_method_first_observation_after_freeze_retains_identity_and_brand(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var P=NamedNodeMap.prototype;Object.freeze(P);var x=document.getElementById('h1');x.title='first';var map=x.attributes,attr=x.getAttributeNode('title'),a=Object.getOwnPropertyDescriptor(P,'getNamedItemNS'),method=a.value;if(typeof method!=='function'||a.get!==undefined||!a.enumerable||a.writable||a.configurable||method.name!=='getNamedItemNS'||method.length!==2||map.getNamedItemNS!==method||P.getNamedItemNS!==method)throw 'frozen first-observed native data method';if(method.call(map,null,'title')!==attr||method.call(map,'','title')!==attr||method.call(map,'urn:other','title')!==null||method.call(map,null,'absent')!==null)throw 'actual namespace attribute authority';var calls=0;if(method.call(map,{toString:function(){calls++;return '';}},{toString:function(){calls++;return 'title';}})!==attr||calls!==2)throw 'single namespace argument conversion';var caught=false;try{method.call({}, {toString:function(){calls++;return '';}},{toString:function(){calls++;return 'title';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls!==2)throw 'map brand before argument conversion';caught=false;try{new method();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'native method is not constructor';x.title='changed';if(method.call(map,null,'title')!==attr||attr.value!=='changed'||x.getAttributeNode('title')!==attr||Object.getOwnPropertyDescriptor(P,'getNamedItemNS').value!==method)throw 'stable live attribute identity';"#);
}
